mapper.select:
select b.*, z.DZZMC,x.hzmc as XJFSMC,
fb.ZZLB
from ZZ_BZJCXX b
inner join ZZ_ZZQKXX z on b.dzzdm= z.dzzdm
left join Zzzd_xjfsdm x on b.xjfs=x.bm
left join ZZ_ZZQKXXFB fb on z.DZZDM = fb.dzzdm
where 1=1

    and b.dzzdm like concat('%',#{dzzdm},'%')


    and b.ldjtjc like concat('%',#{ldjtjc},'%')


    and z.dzzmc like concat('%',#{dzzmc},'%')


    and b.xjfs = #{xjfs}


    and b.gjjmrq >= #{gjjmrq_begin}


    and b.gjjmrq  <=  #{gjjmrq_end}


    and SUBSTR(b.dzzdm,1,12) in(select dzzdm from ZZ_DZZFBQK where zzfb= #{zzfbType})

/*所属党组织代码*/

    and b.dzzdm =#{ssdzzdm}


    and fb.zzlb in

        #{zzlb}



    and fb.jczzfl in

        #{jczzfl}



    and fb.LDJTJC=b.LDJTJC

order by b.dzzdm,b.ldjtjc desc

select c.*, z.DZZMC,rzfs.hzmc as RZFSMC, zwmc.hzmc as ZWMCMC, zwjb.hzmc as ZWJBMC, zzjzqk.HZMC as ZZJZQKMC, uspoint.LDRYLXDMC,jszw.hzmc as JSZWMC, zzfb.ZZLB, bzjcxx.LDJTDXRQ from ZZ_BZCYXX c inner join ZZ_ZZQKXX z on c.dzzdm= z.dzzdm left join zzzd_rzfs rzfs on c.rzfs = rzfs.bm left join Zzzd_zwmc zwmc on c.zwmc = zwmc.bm left join Zd_dzzwjbm zwjb on c.gzwjb = zwjb.bm inner join VM_RYJBXX u on c.RYBM=u.RYBM left join RS_RYJBXXFB fb on u.RYBM=fb.RYBM left join zd_zyjszwdm jszw on u.xjszwmc=jszw.bm left join zzzd_zzjzqk zzjzqk on c.ZZJZQK=zzjzqk.bm left join VW_USERCONTACTPOINT uspoint on c.RYBM=uspoint.RYBM inner join ZZ_ZZQKXXFB zzfb on c.DZZDM=zzfb.DZZDM left join ZZ_BZJCXX bzjcxx on c.JC = bzjcxx.LDJTJC and c.DZZDM = bzjcxx.DZZDM where 1=1
and c.JC=zzfb.LDJTJC
and c.dzzdm like concat('',#{dzzdm},'%')
and c.jc like concat('%',#{ldjtjc},'%')
and z.dzzmc like concat('%',#{dzzmc},'%')
and c.xm like concat('%',#{xm},'%')
and c.rzfs = #{rzfs}
and z.ZZLB in('611','200','271')
and z.ZZLB not in('611','200','271')
and SUBSTR(c.dzzdm,1,12) in(select dzzdm from ZZ_DZZFBQK where zzfb= #{zzfbType})
/*所属党组织代码*/
and c.dzzdm =#{ssdzzdm}
and c.zzjzqk = #{zzjzqk}
and c.zwmc in
#{zwmc}
order by u.XMPY,u.RYJBXXBS

select DZZDM,max(LDJTDXRQ) as LDJTDXRQ from ZZ_BZJCXX c where 1=1
and c.dzzdm =#{dzzdm}
group by DZZDM

select DZZDM,max(LDJTJC) as JC from ZZ_BZJCXX c where 1=1
and c.dzzdm =#{dzzdm}
group by DZZDM

select b.*, z.dzzmc
from ZZ_BZJCXX b
inner join ZZ_ZZQKXX z on b.dzzdm= z.dzzdm
inner join ZZ_ZZQKXXFB fb on z.DZZDM = fb.dzzdm and b.LDJTJC=fb.LDJTJC
where 1=1

    and z.dzzdm =#{dzzdm}


    and b.GJJMRQ is not null and SUBSTR(b.GJJMRQ,1,4)=#{year}


    and z.dzzdm like concat('%',{childDzzdm},'%') and z.dzzdm  <>  #{childDzzdm}
